"""Semantic version ordering."""


def _pre_key(pre):
    # SemVer: numeric identifiers sort numerically and before alphanumeric ones.
    parts = []
    for ident in pre.split("."):
        if ident.isdigit():
            parts.append((0, int(ident), ""))
        else:
            parts.append((1, 0, ident))
    return tuple(parts)


def key(version):
    """Sort key: a pre-release (1.0.0-alpha) sorts before its release (1.0.0)."""
    version = version.split("+", 1)[0]  # build metadata is ignored for ordering
    core, sep, pre = version.partition("-")
    nums = tuple(int(x) for x in core.split("."))
    if not sep:
        return nums + ((1,),)
    return nums + ((0, _pre_key(pre)),)
